#pragma once
#include <cstddef>
#include <cstdint>

// Tables of map colors, generated by tools/compile_map_colors.py into
// map_colors_data.cpp. See MapLooks in include/circuit/gameplay/maps.hpp.
namespace circuit::gameplay::map_color_data {

struct Entry {
    const char* block;    // the block's game name
    const char* release;  // "" for every release, else the one it holds for
    std::uint8_t color;   // the base color of its states without water (0: NONE)
    const char* property; // the property whose values change it, or nullptr
    const char* values;   // those values' colors ("value=color,..."), or nullptr
};
extern const Entry entries[];
extern const std::size_t entry_count;
// Blocks whose waterlogged states always draw WATER, and never.
extern const char* const always_water[];
extern const std::size_t always_water_count;
extern const char* const never_water[];
extern const std::size_t never_water_count;

} // namespace circuit::gameplay::map_color_data
